// HasExecution applies the HasEdge predicate on the "execution" edge.
func HasExecution() predicate.ScriptExecutionDetail {
	return predicate.ScriptExecutionDetail(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ExecutionTable, ExecutionColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasExecutionWith applies the HasEdge predicate on the "execution" edge with a given conditions (other predicates).
func HasExecutionWith(preds ...predicate.ScriptExecution) predicate.ScriptExecutionDetail {
	return predicate.ScriptExecutionDetail(func(s *sql.Selector) {
		step := newExecutionStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ScriptExecutionDetail) predicate.ScriptExecutionDetail {
	return predicate.ScriptExecutionDetail(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ScriptExecutionDetail) predicate.ScriptExecutionDetail {
	return predicate.ScriptExecutionDetail(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ScriptExecutionDetail) predicate.ScriptExecutionDetail {
	return predicate.ScriptExecutionDetail(sql.NotPredicates(p))
}
